function validate([grid, x]) {
  if (!Array.isArray(grid) || grid.length < 1) return 'grid needs at least one row.';
  const n = grid[0].length;
  if (n < 1) return 'Each row needs at least one cell.';
  if (grid.some(row => !Array.isArray(row) || row.length !== n)) return 'All rows must have the same length.';
  if (grid.length * n > 100000) return 'grid holds at most 10^5 cells.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 1 || v > 10000))) return 'Each cell is an integer from 1 to 10^4.';
  if (!Number.isInteger(x) || x < 1 || x > 10000) return 'x is an integer from 1 to 10^4.';
  return null;
}

