function minOperations(grid, x) {
  const cells = [];
  for (const row of grid) for (const v of row) cells.push(v);
  const low = Math.min(...cells);
  const high = Math.max(...cells);
  let best = -1;
  // Try every possible common value between the smallest and largest cell.
  for (let t = low; t <= high; t++) {
    let total = 0;
    let ok = true;
    for (const v of cells) {
      const gap = Math.abs(v - t);
      if (gap % x !== 0) { ok = false; break; }
      total += gap / x;
    }
    if (ok && (best === -1 || total < best)) best = total;
  }
  return best;
}

