function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  let m, n, x, top;
  if (size === 'large') {
    const shape = int(0, 3);
    [m, n] = [[100, 100], [1, 100], [100, 1], [int(40, 100), int(40, 100)]][shape];
    x = [1, int(2, 9), int(10, 300), int(1000, 5000)][int(0, 3)];
    top = 10000;
  } else {
    m = int(1, 3);
    n = int(1, 3);
    x = rand() < 0.8 ? int(1, 4) : int(5, 30);
    top = rand() < 0.8 ? 40 : 10000;
  }
  const remainder = int(0, x - 1);
  const lowStep = remainder === 0 ? 1 : 0;
  const highStep = Math.floor((top - remainder) / x);
  const cell = () => {
    if (highStep < lowStep) return int(1, top);
    return remainder + x * int(lowStep, highStep);
  };
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, cell));
  // Sometimes break the shared remainder so that the answer is -1.
  if (x > 1 && rand() < 0.25) {
    const r = int(0, m - 1);
    const c = int(0, n - 1);
    grid[r][c] = grid[r][c] < top ? grid[r][c] + 1 : grid[r][c] - 1;
  }
  return [grid, x];
}
